using FluentAssertions; using Sigov.Domain.Agro; using Sigov.Domain.Agro.Enums; using Xunit;
namespace Sigov.UnitTests.Agro; public sealed class AgroOcorrenciaRuralRulesTests{[Fact] public void Ocorrencia_exige_numero()=>FluentActions.Invoking(()=>new OcorrenciaRural(1,1,2026,"",AgroOcorrenciaTipo.ESTRADA,"Desc","ALTA",AgroOcorrenciaStatus.ABERTA)).Should().Throw<ArgumentException>(); [Fact] public void Ocorrencia_exige_descricao()=>FluentActions.Invoking(()=>new OcorrenciaRural(1,1,2026,"O1",AgroOcorrenciaTipo.ESTRADA,"","ALTA",AgroOcorrenciaStatus.ABERTA)).Should().Throw<ArgumentException>();}
